impl ReplicaToken {
    pub const fn new(rid: ReplicaId) -> (res: ReplicaToken)
        ensures
            res@ == rid,
    {
        ReplicaToken { rid }
    }

    pub const fn clone(&self) -> (res: Self)
        ensures
            res == self,
    {
        ReplicaToken { rid: self.rid }
    }

    pub open spec fn wf(&self, max_replicas: nat) -> bool {
        &&& self.rid < max_replicas
    }

